CREATE TABLE IF NOT EXISTS PLAYERS (player_id INT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(80) NOT NULL UNIQUE, timezone_offset_minutes INT NOT NULL DEFAULT 330, currency CHAR(3) NOT NULL DEFAULT 'INR');
CREATE TABLE IF NOT EXISTS GAMES (game_id INT PRIMARY KEY AUTO_INCREMENT, game_name VARCHAR(120) NOT NULL UNIQUE, genre VARCHAR(60) NOT NULL, color CHAR(7) NOT NULL DEFAULT '#9b8aff');
CREATE TABLE IF NOT EXISTS PLATFORMS (platform_id INT PRIMARY KEY AUTO_INCREMENT, platform_name VARCHAR(60) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS PLAYER_GAME_LIBRARY (player_id INT NOT NULL,game_id INT NOT NULL,platform_id INT NOT NULL,added_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(player_id,game_id,platform_id),FOREIGN KEY(player_id) REFERENCES PLAYERS(player_id),FOREIGN KEY(game_id) REFERENCES GAMES(game_id),FOREIGN KEY(platform_id) REFERENCES PLATFORMS(platform_id));
CREATE TABLE IF NOT EXISTS PLAYER_SESSIONS (session_id INT PRIMARY KEY AUTO_INCREMENT,player_id INT NOT NULL,game_id INT NOT NULL,platform_id INT NOT NULL,session_start DATETIME NOT NULL,session_end DATETIME NULL,duration_minutes INT GENERATED ALWAYS AS (TIMESTAMPDIFF(MINUTE,session_start,session_end)) STORED,active_player INT GENERATED ALWAYS AS (CASE WHEN session_end IS NULL THEN player_id ELSE NULL END) STORED,UNIQUE KEY one_active_session(active_player),FOREIGN KEY(player_id,game_id,platform_id) REFERENCES PLAYER_GAME_LIBRARY(player_id,game_id,platform_id),CHECK(session_end IS NULL OR session_end>=session_start),INDEX idx_sessions_player_date(player_id,session_start),INDEX idx_sessions_game(game_id));
CREATE TABLE IF NOT EXISTS PURCHASES (purchase_id INT PRIMARY KEY AUTO_INCREMENT,player_id INT NOT NULL,game_id INT NOT NULL,amount DECIMAL(12,2) NOT NULL,purchase_type ENUM('Game','In-game') NOT NULL,purchase_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,note VARCHAR(200) NOT NULL DEFAULT '',FOREIGN KEY(player_id) REFERENCES PLAYERS(player_id),FOREIGN KEY(game_id) REFERENCES GAMES(game_id),CHECK(amount>0),INDEX idx_purchases_player_date(player_id,purchase_date),INDEX idx_purchases_game(game_id));
CREATE TABLE IF NOT EXISTS ACHIEVEMENTS (achievement_id INT PRIMARY KEY AUTO_INCREMENT,game_id INT NOT NULL,title VARCHAR(120) NOT NULL,points INT NOT NULL DEFAULT 10,FOREIGN KEY(game_id) REFERENCES GAMES(game_id),CHECK(points>=0));
CREATE TABLE IF NOT EXISTS PLAYER_ACHIEVEMENTS (player_id INT NOT NULL,achievement_id INT NOT NULL,earned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(player_id,achievement_id),FOREIGN KEY(player_id) REFERENCES PLAYERS(player_id),FOREIGN KEY(achievement_id) REFERENCES ACHIEVEMENTS(achievement_id));
CREATE TABLE IF NOT EXISTS PLAYER_LIMITS (player_id INT PRIMARY KEY,daily_playtime_limit INT NOT NULL DEFAULT 180,weekly_playtime_limit INT NOT NULL DEFAULT 1260,monthly_spending_limit DECIMAL(12,2) NOT NULL DEFAULT 3000,FOREIGN KEY(player_id) REFERENCES PLAYERS(player_id),CHECK(daily_playtime_limit>0 AND weekly_playtime_limit>0 AND monthly_spending_limit>0));
CREATE TABLE IF NOT EXISTS LIMIT_HISTORY (history_id INT PRIMARY KEY AUTO_INCREMENT,player_id INT NOT NULL,daily_playtime_limit INT NOT NULL,weekly_playtime_limit INT NOT NULL,monthly_spending_limit DECIMAL(12,2) NOT NULL,effective_from DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),effective_to DATETIME(3) NULL,change_reason VARCHAR(200) NOT NULL DEFAULT 'Initial limits',FOREIGN KEY(player_id) REFERENCES PLAYERS(player_id),INDEX idx_history_player(player_id,effective_from));
